/* @autogenerated */
/** Forma de `config/<env>-config.json`. Cada sección existe siempre: si el fichero no la trae, llega vacía. */
export interface AppConfig {
  /** Nombre del entorno (`environment.name`). */
  name: string;
  meta: MetaConfig;
  /** Una entrada por host lógico de API. */
  api: Record<string, ApiConfig>;
  i18n: I18nConfig;
  tenant: TenantConfig;
  /** Una entrada por identidad (`main`, …). */
  identity: Record<string, IdentityConfig>;
  telemetry: TelemetryConfig;
  theme: Record<string, unknown>;
  layout: Record<string, unknown>;
  data: DataConfig;
}

export interface MetaConfig {
  title?: string;
}

export interface ApiConfig {
  url?: string;
  identity?: string;
  headers?: Record<string, string>;
  'inject-context'?: string[];
}

export interface I18nConfig {
  'default-lang'?: string;
  'available-langs'?: string[];
}

export interface TenantConfig {
  default?: string;
}

export interface IdentityConfig {
  type: string;
  issuer?: string;
  url?: string;
  profile?: string;
  redirect?: string;
  'logout-redirect'?: string;
  'client-id'?: string;
  scope?: string;
  'roles-claim'?: string;
  audience?: string | string[];
  'force-https'?: boolean;
  persistent?: boolean;
  debug?: boolean;
  /** @deprecated PKCE siempre está activo: se ignora con un aviso. */
  pkce?: unknown;
  [extra: string]: unknown;
}

export type LogLevel = 'debug' | 'info' | 'warn' | 'error';

export interface TelemetryConfig {
  /** Sin `name` no se arranca la telemetría. */
  name?: string;
  /** Entorno de despliegue (`deployment.environment.name`): dev, pre, pro… */
  environment?: string;
  exporter?: {
    tracer?: { url: string };
    logger?: { url: string };
  };
  logger?: {
    /** Nivel mínimo que se registra. Por defecto `info`. */
    level?: LogLevel;
    /** Reenvía también `console.*` al colector. Por defecto `false`. */
    'capture-console'?: boolean;
  };
}

export interface DataConfig {
  'token-wait-ms'?: number;
  /** Vida (ms) de la caché de los repositorios; `RepositoryMetadata.ttl` la sustituye por entidad. Por defecto 3000. */
  'cache-ttl'?: number;
  /**
   * Convierte a `Date` cualquier string con forma de fecha ISO en todas las respuestas. Por defecto `false`:
   * los repositorios convierten solo los campos que sus metadatos declaran como fecha.
   */
  'convert-iso-dates'?: boolean;
}

/** Configuración sin cargar: todas las secciones vacías. */
export function emptyConfig(name: string): AppConfig {
  return {
    name,
    meta: {},
    api: {},
    i18n: {},
    tenant: {},
    identity: {},
    telemetry: {},
    theme: {},
    layout: {},
    data: {},
  };
}

// Rutas tipadas: 'meta.title', 'identity.main', 'identity.main.issuer', 'telemetry.logger.level'…
type Prev = [never, 0, 1, 2, 3, 4];

type PathsOf<T, D extends number> = [D] extends [never]
  ? never
  : T extends readonly unknown[]
    ? never
    : T extends object
      ? {
          [K in keyof T & string]: string extends keyof NonNullable<T[K]>
            ? K | `${K}.${string}`
            : NonNullable<T[K]> extends object
              ? K | `${K}.${PathsOf<NonNullable<T[K]>, Prev[D]>}`
              : K;
        }[keyof T & string]
      : never;

type ValueAt<T, P extends string> = P extends `${infer K}.${infer R}`
  ? K extends keyof T
    ? ValueAt<NonNullable<T[K]>, R>
    : never
  : P extends keyof T
    ? T[P]
    : never;

export type ConfigPath = PathsOf<AppConfig, 4>;
export type ConfigPathValue<P extends string> = ValueAt<AppConfig, P>;

export function readPath<P extends ConfigPath>(config: AppConfig, path: P): ConfigPathValue<P> | undefined {
  let node: any = config;
  for (const part of path.split('.')) {
    node = node == null ? undefined : node[part];
  }
  return node;
}
